def planned_pieces_to_courses(apps, schema_editor):
    """Give each participant with planned pieces what the admin now creates: a
    course they teach, and a curriculum on it with a piece plan per planned
    piece. Nothing they were already assigned is changed."""
    StudyParticipant = apps.get_model("studies", "StudyParticipant")
    Course = apps.get_model("courses", "Course")
    Enrollment = apps.get_model("courses", "Enrollment")
    Role = apps.get_model("users", "Role")
    Curriculum = apps.get_model("assignments", "Curriculum")
    CurriculumEntry = apps.get_model("assignments", "CurriculumEntry")
    PiecePlan = apps.get_model("assignments", "PiecePlan")
    PlannedActivity = apps.get_model("assignments", "PlannedActivity")

    participants = StudyParticipant.objects.filter(
        planned_pieces__isnull=False, user__isnull=False
    ).distinct()
    for participant in participants.select_related("study", "user"):
        name = f"{participant.study.name}: {participant.user.email}"
        slug = base = slugify(name, allow_unicode=True)
        for i in itertools.count(1):
            if not Course.objects.filter(slug=slug).exists():
                break
            slug = f"{base}-{i}"
        today = timezone.localdate()
        course = Course.objects.create(
            name=name,
            slug=slug,
            owner=participant.user,
            start_date=today,
            end_date=today + datetime.timedelta(days=365),
        )
        Enrollment.objects.create(
            user=participant.user,
            course=course,
            role=Role.objects.get_or_create(name="Teacher")[0],
        )
        curriculum = Curriculum.objects.create(name=name, course=course)
        planned = participant.planned_pieces.select_related("piece").order_by("id")
        for order, planned_piece in enumerate(planned):
            plan = PiecePlan.objects.create(name=name, piece=planned_piece.piece)
            for i, activity in enumerate(planned_piece.activities.order_by("id")):
                PlannedActivity.objects.create(
                    piece_plan=plan, activity=activity, order=i
                )
            CurriculumEntry.objects.create(
                curriculum=curriculum, piece_plan=plan, order=order
            )
        participant.curriculum = curriculum
        participant.save(update_fields=["curriculum"])


